        disc[v] = low[v] < disc[v] ? low[v] : disc[v];
        stack.add(v);
      }
    }
  }

  if (hasCycle) {
    print('Graph contains a cycle, topological sort not possible.');
  } else {

    List<int> sorted = [];
    for (int i = 0; i < n; i++) {
      if (!onStack[i]) {
        stack.add(i);
        sorted.add(i);
      }
    }

    print('Topological Sort: ${sorted.join(' -> ')}');
  }
}

